/* ---- byte conversion, canonical form, the inversion ---- */

static inline ulong fd_adx_load8_le( const uchar * p ) { ulong v; memcpy( &v, p, 8 ); return v; }
static inline void fd_adx_store8_le( uchar * p, ulong v ) { memcpy( p, &v, 8 ); }
/* zeroing the compiler cannot drop: memset behind a fence on the memory */
static inline void fd_adx_memzero( void * p, ulong n ) { memset( p, 0, n ); __asm__ __volatile__( "" : : "r"(p) : "memory" ); }

/* the value of the 32 bytes with bit 255 cleared, as four 64-bit words */
static inline void fd_fe64_frombytes( ulong r[4], const uchar b[32] ) {
  for( int i=0; i<4; i++ ) r[i] = fd_adx_load8_le( b + 8*i );
  r[3] &= 0x7fffffffffffffffULL;
}

/* canonical words, the value in [0, p): two constant-time conditional subtractions of p cover
   every value below 3p; the kernels keep values below 2p */
static inline void fd_fe64_canon( ulong c[4], const ulong a[4] ) {
  static const ulong P[4] = { 0xffffffffffffffedULL, 0xffffffffffffffffULL, 0xffffffffffffffffULL, 0x7fffffffffffffffULL };
  ulong x[4] = { a[0], a[1], a[2], a[3] };
  for( int pass=0; pass<2; pass++ ) {
    ulong t[4], borrow = 0;
    for( int i=0; i<4; i++ ) {
      uint128 d = (uint128)x[i] - P[i] - borrow;
      t[i] = (ulong)d; borrow = (ulong)(d >> 64) & 1ULL;
    }
    ulong keep = 0 - borrow;  /* all ones when x < p */
    for( int i=0; i<4; i++ ) x[i] = (x[i] & keep) | (t[i] & ~keep);
  }
  for( int i=0; i<4; i++ ) c[i] = x[i];
}

static inline void fd_fe64_tobytes( uchar out[32], const ulong a[4] ) {
  ulong c[4]; fd_fe64_canon( c, a );
  for( int i=0; i<4; i++ ) fd_adx_store8_le( out + 8*i, c[i] );
}
static inline int fd_fe64_sgn( const ulong a[4] ) { ulong c[4]; fd_fe64_canon( c, a ); return (int)(c[0] & 1ULL); }

/* a^(2^252-3) over the assembly kernels */
static inline void fd_fe64_pow22523( ulong r[4], const ulong a[4] ) {
  ulong t0[4], t1[4], t2[4];
  fd_fe64_sqr( t0, a );
  fd_fe64_sqr( t1, t0 ); for( int i=1; i<2; i++ ) fd_fe64_sqr( t1, t1 );
  fd_fe64_mul( t1, a, t1 );
  fd_fe64_mul( t0, t0, t1 );
  fd_fe64_sqr( t0, t0 );
  fd_fe64_mul( t0, t1, t0 );
  fd_fe64_sqr( t1, t0 ); for( int i=1; i<5; i++ ) fd_fe64_sqr( t1, t1 );
  fd_fe64_mul( t0, t1, t0 );
  fd_fe64_sqr( t1, t0 ); for( int i=1; i<10; i++ ) fd_fe64_sqr( t1, t1 );
  fd_fe64_mul( t1, t1, t0 );
  fd_fe64_sqr( t2, t1 ); for( int i=1; i<20; i++ ) fd_fe64_sqr( t2, t2 );
  fd_fe64_mul( t1, t2, t1 );
  fd_fe64_sqr( t1, t1 ); for( int i=1; i<10; i++ ) fd_fe64_sqr( t1, t1 );
  fd_fe64_mul( t0, t1, t0 );
  fd_fe64_sqr( t1, t0 ); for( int i=1; i<50; i++ ) fd_fe64_sqr( t1, t1 );
  fd_fe64_mul( t1, t1, t0 );
  fd_fe64_sqr( t2, t1 ); for( int i=1; i<100; i++ ) fd_fe64_sqr( t2, t2 );
  fd_fe64_mul( t1, t2, t1 );
  fd_fe64_sqr( t1, t1 ); for( int i=1; i<50; i++ ) fd_fe64_sqr( t1, t1 );
  fd_fe64_mul( t0, t1, t0 );
  fd_fe64_sqr( t0, t0 ); for( int i=1; i<2; i++ ) fd_fe64_sqr( t0, t0 );
  fd_fe64_mul( t0, t0, a );
  memcpy( r, t0, 32 );
}

/* 1/a (a != 0) by the exponentiation chain: a^(p-2) with p - 2 = 8 (2^252 - 3) + 3 */
static inline void fd_fe64_inv_chain( ulong r[4], const ulong a[4] ) {
  ulong t[4], a3[4];
  fd_fe64_pow22523( t, a );
  fd_fe64_sqr( t, t ); fd_fe64_sqr( t, t ); fd_fe64_sqr( t, t );
  fd_fe64_sqr( a3, a ); fd_fe64_mul( a3, a3, a );
  fd_fe64_mul( r, t, a3 );
}

/* 1/a as a checked result: s2n-bignum's divstep inversion proposes r, the generated multiply
   and canonical form confirm a r = 1; the exponentiation chain answers when they do not (a = 0,
   or a proposal that is wrong). The confirmation is the only step the result depends on. */
void bignum_inv_p25519( ulong z[4], const ulong x[4] );
static inline void fd_fe64_inv( ulong r[4], const ulong a[4] ) {
  ulong ac[4], t[4], c[4];
  fd_fe64_canon( ac, a );
  bignum_inv_p25519( r, ac );
  fd_fe64_mul( t, r, a ); fd_fe64_canon( c, t );
  if( (c[0] ^ 1ULL) | c[1] | c[2] | c[3] ) fd_fe64_inv_chain( r, a );
}

